  if(cloudReady){
    try{const {db,fs}=await getFirebaseContext(),snap=await fs.getDocs(fs.collection(db,"publicProfiles"));snap.forEach(docSnap=>profileMap[docSnap.id]=docSnap.data())}catch(error){console.warn("rank load",error)}
  }
