  iceCrystalPrincess:{name:"เจ้าหญิงคริสตัลน้ำแข็ง",image:"jelly_v2_ice_crystal_princess.png?v=1"},
  sacredLotusEmperor:{name:"จักรพรรดิดอกบัวศักดิ์สิทธิ์",image:"jelly_v2_sacred_lotus_emperor.png?v=1"},
