  async function buyMedicineQty(key,qty){qty=Math.max(1,Math.min(99,Math.floor(Number(qty)||1)));const med=Y26_MEDICINES[key];if(!med)return;try{await settlePendingCloudSave();const {db,fs}=await getFirebaseContext(),saveRef=fs.doc(db,"saves",currentMemberKey),profRef=fs.doc(db,"publicProfiles",currentMemberKey);let next;await fs.runTransaction(db,async tx=>{const snap=await tx.get(saveRef);if(!snap.exists())throw new Error("ไม่พบเซฟสมาชิก");const s=normalizeState(snap.data(),currentMember),total=med.price*qty;if(Number(s.merit||0)<total)throw new Error(`กุศลไม่พอ ต้องใช้ ${total} กุศล`);s.merit-=total;s.medicines[key]=(Number(s.medicines[key])||0)+qty;next=s;tx.set(saveRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(profRef,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),merit:s.merit,initialized:true,updatedAt:fs.serverTimestamp()},{merge:true})});Y26_applyOwnState(next);updateMeritUI();showShop("medicine")}catch(e){message("ซื้อยาไม่ได้",e.message||"กรุณาลองใหม่")}}

  function polishShop(tab){
    document.querySelectorAll(".shop-card").forEach(card=>{card.classList.add("ynu-shop-card");const img=card.querySelector(":scope > img");if(img&&!img.closest(".ynu-shop-image-box")){const box=document.createElement("div");box.className="ynu-shop-image-box";img.before(box);box.appendChild(img)}const texts=[...card.querySelectorAll("small")];if(texts.length>1&&!card.querySelector(".ynu-condition-btn")){const long=texts.find(x=>x.textContent.trim().length>48);if(long){const b=document.createElement("button");b.className="ynu-condition-btn";b.type="button";b.textContent="เงื่อนไข";long.classList.add("ynu-condition-copy","hidden");long.before(b);b.onclick=()=>long.classList.toggle("hidden")}}});
    if(tab==="specials")appendNewShopCards();
    if(tab==="medicine")document.querySelectorAll("[data-buy-medicine]").forEach(btn=>{const key=btn.dataset.buyMedicine,card=btn.closest(".medicine-shop-card,.shop-card");if(!card||card.querySelector(".ynu-med-qty"))return;const label=document.createElement("label");label.className="ynu-qty ynu-med-qty";label.innerHTML='จำนวน <input type="number" min="1" max="99" value="1">';btn.before(label);btn.onclick=()=>buyMedicineQty(key,label.querySelector("input").value)});
  }
  const _showShop=showShop;showShop=function(tab){const r=_showShop(tab);setTimeout(()=>polishShop(tab),0);return r};if($("shopNavBtn"))$("shopNavBtn").onclick=()=>showShop("home");

  /* ---------- friend visit nav remains usable ---------- */
