/* ======================================================================
   V218 MAJOR FIX — ADMIN GIFT DELIVERY + CAMPAIGN SCROLL FOUNDATION
   1) Recover pending gifts even when mailbox history is crowded/missing.
   2) Admin global bundles are delivered as per-member gift documents.
   3) Every new admin delivery has an audit record.
   ====================================================================== */
(function V218_MAJOR_GIFT_DELIVERY_FIX(){
  const V218_GIFT_MAIL_LIMIT=200;
  const V218_PENDING_GIFT_LIMIT=200;

  function V218_memberNameByKey(key){
    const found=Object.keys(MEMBERS).find(name=>memberKeyFromName(name)===String(key||""));
    return found||String(key||"");
  }
  function V218_bundleSummary(items){
    return (Array.isArray(items)?items:[]).map(i=>`${i.name||i.key} ×${Math.max(1,Number(i.qty)||1)}`).join(" • ");
  }
  function V218_validateGiftItems(items){
    if(!Array.isArray(items)||!items.length)throw new Error("กรุณาเลือกของอย่างน้อย 1 รายการ");
    // Test against a normalized clone before anything is written to Firebase.
    const sample=normalizeState(cloneData(ownState||state),currentMember||"Aida");
    for(const i of items)addGiftItemToState(sample,{itemType:i.type,itemKey:i.key,qty:i.qty});
  }
  function V218_lockButton(id,text){
    const b=$(id);if(!b)return()=>{};
    const oldText=b.textContent;b.disabled=true;b.textContent=text||"กำลังส่ง...";
    return()=>{if(document.body.contains(b)){b.disabled=false;b.textContent=oldText}};
  }

  /* Mailbox recovery: merge normal mailbox entries with every PENDING gift
     addressed to this member. If an old mailbox record disappeared or fell
     outside the visible history, the gift still reappears and can be claimed. */
  fetchMailboxItems=async function(){
    if(!cloudReady||!currentMemberKey)return[];
    const {db,fs}=await getFirebaseContext(),mailRef=fs.collection(db,"mailboxes",currentMemberKey,"items");
    let rows=[];
    try{
      const snap=await fs.getDocs(fs.query(mailRef,fs.orderBy("createdAt","desc"),fs.limit(V218_GIFT_MAIL_LIMIT)));
      snap.forEach(d=>rows.push({id:d.id,...d.data()}));
    }catch(error){
      const snap=await fs.getDocs(mailRef);snap.forEach(d=>rows.push({id:d.id,...d.data()}));
      rows=rows.sort((a,b)=>timestampMillis(b.createdAt)-timestampMillis(a.createdAt)).slice(0,V218_GIFT_MAIL_LIMIT);
    }

    try{
      const giftsRef=fs.collection(db,"gifts");
      let giftSnap;
      try{
        giftSnap=await fs.getDocs(fs.query(giftsRef,fs.where("toKey","==",currentMemberKey),fs.limit(V218_PENDING_GIFT_LIMIT)));
      }catch(error){
        console.warn("V218 pending gift recovery query",error);
        giftSnap=null;
      }
      if(giftSnap){
        const known=new Set(rows.map(x=>String(x.giftId||x.id)));
        giftSnap.forEach(d=>{
          const g=d.data()||{};
          if(g.status!=="pending"||known.has(d.id))return;
          const items=Array.isArray(g.items)?g.items:[{name:g.itemName||g.itemKey||"ของขวัญ",qty:g.qty||1}];
          rows.push({
            id:d.id,giftId:d.id,type:"gift",source:g.fromKey==="aida"?"yainoo":"friend",
            fromKey:g.fromKey||"",fromName:g.fromName||"",
            title:g.fromKey==="aida"?"ยัยหนูส่งกล่องของขวัญให้คุณ 🎁":"มีของขวัญส่งถึงคุณ 🎁",
            text:V218_bundleSummary(items),read:false,resolved:false,recovered:true,createdAt:g.createdAt
          });
        });
      }
    }catch(error){console.warn("V218 recover pending gifts",error)}

    return rows.sort((a,b)=>timestampMillis(b.createdAt)-timestampMillis(a.createdAt));
  };

  /* Individual admin send: atomic gift + mailbox + audit, then verify both
     documents really exist before showing the success message. */
  sendAdminBundleGift=async function(catalog){
    if(adminProfile?.role!=="admin")return;
    const unlock=V218_lockButton("adminSendBundleBtn","กำลังตรวจและส่ง...");
    try{
      const targetSelect=$("adminBundleTarget"),targetKey=String(targetSelect?.value||"");
      const targetName=V218_memberNameByKey(targetKey);
      const validKeys=new Set(Object.keys(MEMBERS).map(memberKeyFromName));
      const items=selectedAdminBundle(catalog,"admin-bundle");
      if(!targetKey||!validKeys.has(targetKey))throw new Error("ไม่พบไอดีสมาชิกปลายทาง");
      V218_validateGiftItems(items);

      const {db,fs}=await getFirebaseContext(),giftRef=fs.doc(fs.collection(db,"gifts"));
      const mailRef=fs.doc(db,"mailboxes",targetKey,"items",giftRef.id);
      const auditRef=fs.doc(db,"adminGiftDeliveries",giftRef.id);
      const cleanItems=items.map(i=>({type:i.type,key:i.key,name:i.name,qty:Math.max(1,Math.floor(Number(i.qty)||1))}));
      const summary=V218_bundleSummary(cleanItems),batch=fs.writeBatch(db);
      batch.set(giftRef,{fromKey:"aida",fromName:"Aida",toKey:targetKey,toName:targetName,bundle:true,items:cleanItems,status:"pending",deliveryMode:"individual",createdAt:fs.serverTimestamp()});
      batch.set(mailRef,{source:"yainoo",type:"gift",giftId:giftRef.id,fromKey:"aida",fromName:"Aida",title:"ยัยหนูส่งกล่องของขวัญให้คุณ 🎁",text:summary,read:false,resolved:false,createdAt:fs.serverTimestamp()});
      batch.set(auditRef,{deliveryId:giftRef.id,mode:"individual",recipientCount:1,recipients:[targetKey],recipientNames:[targetName],items:cleanItems,status:"committed",createdAt:fs.serverTimestamp()});
      await batch.commit();

      const [giftCheck,mailCheck]=await Promise.all([fs.getDoc(giftRef),fs.getDoc(mailRef)]);
      if(!giftCheck.exists()||!mailCheck.exists())throw new Error("ระบบบันทึกของขวัญไม่ครบ กรุณาส่งใหม่");
      showWeatherToast(`✅ ส่งถึง ${targetName} แล้ว • ตรวจพบกล่องในระบบ`);
      await showAdminCenter();
    }catch(error){message("ส่งของไม่ได้",error.message||"กรุณาลองใหม่")}finally{unlock()}
  };

  /* Global admin send: no longer relies on one broadcast card. Create a real
     pending gift + mailbox item for EVERY recipient. One batch supports the
     current roster and 100-member future roster (<500 writes). */
  sendAdminGlobalBundleGift=async function(catalog){
    if(adminProfile?.role!=="admin")return;
    const unlock=V218_lockButton("adminSendGlobalBundleBtn","กำลังส่งให้ทุกคน...");
    try{
      const items=selectedAdminBundle(catalog,"admin-global"),includeAida=Boolean($("adminIncludeAida")?.checked);
      V218_validateGiftItems(items);
      const recipients=Object.keys(MEMBERS).filter(name=>includeAida||name!=="Aida").map(name=>({name,key:memberKeyFromName(name)}));
      if(!recipients.length)throw new Error("ไม่พบสมาชิกปลายทาง");
      if(recipients.length*2+1>480)throw new Error("จำนวนสมาชิกมากเกินชุดส่งเดียว กรุณาแบ่งรอบ");

      const {db,fs}=await getFirebaseContext(),batch=fs.writeBatch(db),groupRef=fs.doc(fs.collection(db,"adminGiftDeliveries"));
      const cleanItems=items.map(i=>({type:i.type,key:i.key,name:i.name,qty:Math.max(1,Math.floor(Number(i.qty)||1))}));
      const summary=V218_bundleSummary(cleanItems);
      const giftIds=[];
      recipients.forEach(r=>{
        const giftRef=fs.doc(fs.collection(db,"gifts")),mailRef=fs.doc(db,"mailboxes",r.key,"items",giftRef.id);
        giftIds.push(giftRef.id);
        batch.set(giftRef,{fromKey:"aida",fromName:"Aida",toKey:r.key,toName:r.name,bundle:true,items:cleanItems,status:"pending",deliveryMode:"global-member",deliveryGroupId:groupRef.id,createdAt:fs.serverTimestamp()});
        batch.set(mailRef,{source:"yainoo",type:"gift",giftId:giftRef.id,fromKey:"aida",fromName:"Aida",title:"ยัยหนูส่งกล่องของขวัญให้คุณ 🎁",text:summary,read:false,resolved:false,deliveryGroupId:groupRef.id,createdAt:fs.serverTimestamp()});
      });
      batch.set(groupRef,{deliveryId:groupRef.id,mode:"global",recipientCount:recipients.length,recipients:recipients.map(r=>r.key),recipientNames:recipients.map(r=>r.name),giftIds,items:cleanItems,status:"committed",createdAt:fs.serverTimestamp()});
      await batch.commit();
      showWeatherToast(`✅ ส่งกล่องรายคนสำเร็จ ${recipients.length}/${recipients.length} ไอดี`);
      await showAdminCenter();
    }catch(error){message("ส่งของขวัญไม่สำเร็จ",error.message||"กรุณาลองใหม่")}finally{unlock()}
  };

  /* Small audit viewer so Admin can verify what the app recorded. */
  async function V218_showGiftAudit(){
    try{
      const {db,fs}=await getFirebaseContext();let rows=[];
      try{
        const snap=await fs.getDocs(fs.query(fs.collection(db,"adminGiftDeliveries"),fs.orderBy("createdAt","desc"),fs.limit(20)));
        snap.forEach(d=>rows.push({id:d.id,...d.data()}));
      }catch(error){
        const snap=await fs.getDocs(fs.collection(db,"adminGiftDeliveries"));snap.forEach(d=>rows.push({id:d.id,...d.data()}));
        rows.sort((a,b)=>timestampMillis(b.createdAt)-timestampMillis(a.createdAt));rows=rows.slice(0,20);
      }
      $("modalContent").innerHTML=`<section class="feature-panel admin-panel v218-gift-audit"><h2>📦 ประวัติการส่งของล่าสุด</h2><p class="feature-subtitle">รายการนี้เป็นหลักฐานที่ Firebase บันทึกหลังส่งสำเร็จ</p><div class="v218-audit-list">${rows.length?rows.map(r=>`<article><b>${r.mode==="global"?`ส่งทุกคน ${Number(r.recipientCount)||0} ไอดี`:`ส่งให้ ${safeHtml((r.recipientNames||[])[0]||"สมาชิก")}`}</b><span>${safeHtml(V218_bundleSummary(r.items||[]))}</span><small>${bangkokTimeText(r.createdAt)} น. • ${safeHtml(r.status||"committed")}</small></article>`).join(""):'<p class="empty-feature">ยังไม่มีประวัติจากระบบ V218</p>'}</div><button id="v218AuditBack" class="secondary-action" type="button">กลับศูนย์แอดมิน</button></section>`;
      $("v218AuditBack").onclick=showAdminCenter;openModal();
    }catch(error){message("เปิดประวัติไม่ได้",error.message||"กรุณาลองใหม่")}
  }
  const V218_showAdminBase=showAdminCenter;
  showAdminCenter=async function(){
    await V218_showAdminBase();
    const panel=document.querySelector(".admin-panel");
    if(panel&&!$("v218GiftAuditBtn")){
      const btn=document.createElement("button");btn.id="v218GiftAuditBtn";btn.type="button";btn.className="secondary-action";btn.textContent="📦 ตรวจประวัติการส่งของล่าสุด";
      btn.onclick=V218_showGiftAudit;panel.insertBefore(btn,panel.children[2]||null);
    }
  };

  window.YAINOO_BUILD="V218-MAJOR-GIFT-CAMPAIGN-SCROLL-FIX";
  console.info("V218 major gift delivery recovery loaded");
})();


/* ======================================================================
   V221 — Friend grass drops: 30-minute rounds + reliable confirmation
   - Friend farms only; never your own farm
   - Farms 1–4
   - New deterministic round every 30 minutes
   - Buttons live directly on gameScreen (not inside pointer-events:none pet layer)
   - User must confirm; Firebase write completes before showing success
   - All three grasses are real Specials inventory items and admin-sendable
   ====================================================================== */
(function V221_FRIEND_GRASS_SYSTEM(){
  const ITEMS={
    friendGrassGreen:{name:"หญ้าสีเขียว",image:"friend-grass-green.png?v=221",kind:"forage",group:"friendForage",description:"พบจากการเยี่ยมสวนเพื่อน • พบได้บ่อยที่สุด"},
    friendGrassYellow:{name:"หญ้าสีเหลือง",image:"friend-grass-yellow.png?v=221",kind:"forage",group:"friendForage",description:"พบจากการเยี่ยมสวนเพื่อน • พบรองลงมา"},
    friendGrassRed:{name:"หญ้าสีแดง",image:"friend-grass-red.png?v=221",kind:"forage",group:"friendForage",description:"พบจากการเยี่ยมสวนเพื่อน • หายากที่สุด"}
  };
  const KEYS=Object.keys(ITEMS),KEYSET=new Set(KEYS),ROUND_MS=30*60*1000;
  Object.assign(SPECIAL_ITEMS,ITEMS);
  const POINTS={1:[[18,28],[32,23],[50,28],[68,22],[22,49],[42,46],[62,50],[77,42],[31,68],[56,67]],2:[[18,28],[32,23],[50,28],[68,22],[22,49],[42,46],[62,50],[77,42],[31,68],[56,67]],3:[[18,28],[32,23],[50,28],[68,22],[22,49],[42,46],[62,50],[77,42],[31,68],[56,67]],4:[[18,28],[32,23],[50,28],[68,22],[22,49],[42,46],[62,50],[77,42],[31,68],[56,67]]};

  function hash(str){let h=2166136261>>>0;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
  function rng(seed){let t=seed>>>0;return()=>{t+=0x6D2B79F5;let x=Math.imul(t^t>>>15,1|t);x^=x+Math.imul(x^x>>>7,61|x);return((x^x>>>14)>>>0)/4294967296}}
  function weighted(rand,pairs){let roll=rand()*pairs.reduce((s,p)=>s+p[1],0);for(const [key,w] of pairs){roll-=w;if(roll<=0)return key}return pairs.at(-1)[0]}
  function shuffle(arr,rand){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
  function farmNo(){try{return Math.max(1,Math.min(4,Number(typeof currentFarmNo==="function"?currentFarmNo():Number(farmPlotPage||0)+1)||1))}catch{return 1}}
  function roundKey(){return Math.floor(gameNow()/ROUND_MS)}
  function friendKey(){return String(visitContext?.memberKey||"")}
  function friendName(){return String(visitContext?.name||"")}
  function isAidaFarm(){return friendKey()==="aida"||friendName().toLowerCase()==="aida"}
  function claimStore(s){if(!s.friendForageClaims||typeof s.friendForageClaims!=="object")s.friendForageClaims={};return s.friendForageClaims}
  function pruneClaims(s){const store=claimStore(s),now=roundKey();Object.keys(store).forEach(k=>{const m=String(k).match(/:r(\d+)$/);if(m&&now-Number(m[1])>144)delete store[k]})}
  function dropId(slot){return `v221:${currentMemberKey}:${friendKey()}:f${farmNo()}:s${slot}:r${roundKey()}`}
  function hasClaimed(id){return Boolean(claimStore(ownState||state||{})[id])}
  function buildDrops(){
    if(!visitContext||!currentMemberKey)return[];
    const rand=rng(hash(`${currentMemberKey}|${friendKey()}|farm${farmNo()}|round${roundKey()}`)),aida=isAidaFarm();let count=0;
    /* Same spawn balance as before, now rerolled every 30 minutes. */
    if(aida){count=2+Math.floor(rand()*3);}else{if(rand()<.55)count++;if(rand()<.28)count++;if(rand()<.08)count++;}
    if(!count)return[];
    const points=shuffle(POINTS[farmNo()]||POINTS[1],rand),drops=[];
    for(let i=0;i<count;i++){
      const key=weighted(rand,[["friendGrassGreen",50],["friendGrassYellow",30],["friendGrassRed",20]]),pt=points[i%points.length]||[50,50],id=dropId(i);
      if(hasClaimed(id))continue;drops.push({id,key,name:ITEMS[key].name,image:ITEMS[key].image,x:pt[0]+(rand()*3-1.5),y:pt[1]+(rand()*3-1.5),rarity:key==="friendGrassRed"?"rare":key==="friendGrassYellow"?"uncommon":"common"});
    }
    return drops;
  }
  function clearDrops(){document.querySelectorAll('.friend-forage-drop,.friend-forage-tip').forEach(n=>n.remove())}
  function renderDrops(){
    clearDrops();if(!visitContext)return;const host=$("gameScreen");if(!host||host.classList.contains("hidden"))return;const drops=buildDrops();if(!drops.length)return;
    const tip=document.createElement("div");tip.className="friend-forage-tip";tip.textContent=isAidaFarm()?"🌿 สวนไอด้ามีของดรอปให้ลุ้นมากขึ้น":"🌿 มีหญ้าซ่อนอยู่ในสวนเพื่อน";host.appendChild(tip);
    drops.forEach(drop=>{const btn=document.createElement("button");btn.type="button";btn.className=`friend-forage-drop ${drop.key==="friendGrassGreen"?"friend-forage-green":drop.key==="friendGrassYellow"?"friend-forage-yellow":"friend-forage-red"}`;btn.dataset.rarity=drop.rarity;btn.style.left=`${drop.x}%`;btn.style.top=`${drop.y}%`;btn.innerHTML=`<img src="${drop.image}" alt="${safeHtml(drop.name)}">`;btn.onclick=e=>{e.preventDefault();e.stopPropagation();if(btn.dataset.tapBusy==="1")return;btn.dataset.tapBusy="1";btn.classList.add("is-tapped");requestAnimationFrame(()=>{showClaimConfirm(drop);setTimeout(()=>{btn.dataset.tapBusy="0";btn.classList.remove("is-tapped")},180)})};host.appendChild(btn)});
  }
  let grassCampaignActiveCache={value:true,checkedAt:0};
  async function grassCampaignActive(fs,db,id){
    const now=gameNow();
    if(now-grassCampaignActiveCache.checkedAt<60000)return grassCampaignActiveCache.value;
    try{const snap=await fs.getDoc(fs.doc(db,"campaigns",id));grassCampaignActiveCache={value:!snap.exists()||(snap.data()||{}).active!==false,checkedAt:now}}
    catch{grassCampaignActiveCache={value:true,checkedAt:now}}
    return grassCampaignActiveCache.value;
  }
  function showClaimConfirm(drop){
    if(!visitContext||hasClaimed(drop.id)){renderDrops();return}
    $("modalContent").innerHTML=`<section class="feature-panel friend-grass-confirm"><img class="friend-grass-confirm-icon" src="${drop.image}" alt="${safeHtml(drop.name)}"><h2>คุณได้รับ ${safeHtml(drop.name)} ×1</h2><p>กดยืนยันเพื่อรับเข้ากระเป๋าของคุณ</p><button id="friendGrassConfirmBtn" class="primary-spooky-action" type="button">ยืนยันรับเข้ากระเป๋า</button><button id="friendGrassCancelBtn" class="secondary-action" type="button">ยังไม่เก็บ</button></section>`;
    openModal();$("friendGrassConfirmBtn").onclick=()=>claim(drop);$("friendGrassCancelBtn").onclick=closeModal;
  }
  async function claim(drop){
    if(!visitContext||!currentMemberKey)return;const btn=$("friendGrassConfirmBtn");if(btn){btn.disabled=true;btn.textContent="รับแล้ว ✓"}
    const before=normalizeState(cloneData(ownState||state),currentMember),local=normalizeState(cloneData(ownState||state),currentMember),store=claimStore(local);
    if(store[drop.id]){closeModal();renderDrops();return}
    if(!local.specials||typeof local.specials!=="object")local.specials={};local.specials[drop.key]=(Number(local.specials[drop.key])||0)+1;store[drop.id]=gameNow();incrementMissionOn(local,"dailyCollectGrass",1);pruneClaims(local);ownState=local;if(!visitContext)state=local;saveLocalOnly(local);try{save()}catch(_){}closeModal();renderDrops();showReceived(drop);
    Promise.resolve().then(async()=>{
      try{
        const {db,fs}=await getFirebaseContext(),saveRef=fs.doc(db,"saves",currentMemberKey);let next,grassCampaignAdd=0;const grassCampaignId="grass-harvest-7d-v1",campaignActive=await grassCampaignActive(fs,db,grassCampaignId);
        await fs.runTransaction(db,async tx=>{const snap=await tx.get(saveRef);if(!snap.exists())throw new Error("ไม่พบเซฟสมาชิก");const st=normalizeState(snap.data(),currentMember);assertCurrentCloudSession(snap.data(),currentMember);const cloudStore=claimStore(st);if(cloudStore[drop.id]){next=st;return}if(!st.specials||typeof st.specials!=="object")st.specials={};st.specials[drop.key]=(Number(st.specials[drop.key])||0)+1;cloudStore[drop.id]=gameNow();incrementMissionOn(st,"dailyCollectGrass",1);pruneClaims(st);if(campaignActive)grassCampaignAdd=drop.key==="friendGrassRed"?5:drop.key==="friendGrassYellow"?3:1;next=st;tx.set(saveRef,{...cloneData(st),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false})});
        if(next){ownState=normalizeState(next,currentMember);saveLocalOnly(ownState)}if(grassCampaignAdd>0)window.YN_R7_campaignIncrement(grassCampaignId,grassCampaignAdd).catch(()=>{});
      }catch(error){console.error("friend grass persist",error);/* keep local reward; queued save can retry, never make a successful tap vanish */try{save();flushCloudSave?.()}catch(_){}showWeatherToast?.("🌿 เก็บเข้ากระเป๋าแล้ว • ระบบจะบันทึกซ้ำอัตโนมัติ")}
    });
  }
  function showReceived(drop){
    $("modalContent").innerHTML=`<section class="feature-panel friend-grass-confirm friend-grass-received"><img class="friend-grass-confirm-icon" src="${drop.image}" alt="${safeHtml(drop.name)}"><h2>คุณได้รับ ${safeHtml(drop.name)} ×1</h2><p>เข้ากระเป๋าเรียบร้อยแล้ว</p><button id="friendGrassDoneBtn" class="primary-spooky-action" type="button">ตกลง</button></section>`;openModal();$("friendGrassDoneBtn").onclick=closeModal;
  }

  async function ensureAdminStock(){
    if(currentMember!=="Aida"||adminProfile?.role!=="admin"||!ownState)return;let changed=false;if(!ownState.specials||typeof ownState.specials!=="object")ownState.specials={};
    KEYS.forEach(key=>{if((Number(ownState.specials[key])||0)<ADMIN_STOCK_QTY){ownState.specials[key]=ADMIN_STOCK_QTY;changed=true}});if(changed){state=ownState;saveLocalOnly(ownState);try{await settlePendingCloudSave();save()}catch(e){console.warn("V221 grass stock save",e)}}
  }
  async function useGrass(key){
    if(!KEYSET.has(key)||!cloudReady||!currentMemberKey)return;const item=ITEMS[key];try{await settlePendingCloudSave();const {db,fs}=await getFirebaseContext(),saveRef=fs.doc(db,"saves",currentMemberKey);let next;await fs.runTransaction(db,async tx=>{const snap=await tx.get(saveRef);if(!snap.exists())throw new Error("ไม่พบเซฟสมาชิก");const s=normalizeState(snap.data(),currentMember);assertCurrentCloudSession(snap.data(),currentMember);const have=Number(s.specials?.[key])||0;if(have<1)throw new Error(`ไม่มี ${item.name} ในกระเป๋า`);s.specials[key]=have-1;next=s;tx.set(saveRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false})});ownState=normalizeState(next,currentMember);if(!visitContext)state=ownState;saveLocalOnly(ownState);inventory("specials");showWeatherToast(`🌿 ใช้ ${item.name} ×1 แล้ว`)}catch(e){message("ใช้หญ้าไม่ได้",e.message||"กรุณาลองใหม่")}}
  function injectUseButtons(){
    const panel=document.querySelector(".inventory-panel");if(!panel)return;panel.querySelectorAll(".inventory-item").forEach(card=>{const img=card.querySelector("img");if(!img)return;const src=String(img.getAttribute("src")||""),key=KEYS.find(k=>src.includes(ITEMS[k].image.split("?")[0]));if(!key||card.querySelector("[data-use-friend-grass]"))return;const count=Number((ownState||state)?.specials?.[key])||0,btn=document.createElement("button");btn.type="button";btn.dataset.useFriendGrass=key;btn.className="friend-grass-use-btn";btn.textContent=count>0?"ใช้ ×1":"ไม่มี";btn.disabled=count<=0;btn.onclick=()=>useGrass(key);card.appendChild(btn)})
  }

  /* Explicitly ensure the three items are present in Admin send catalog even if
     another late wrapper cached an older SPECIAL_ITEMS list. */
  if(typeof adminGiftCatalog==="function"){
    const baseCatalog=adminGiftCatalog;adminGiftCatalog=function(){const list=baseCatalog();KEYS.forEach(key=>{if(!list.some(e=>e.type==="special"&&e.key===key))list.push({type:"special",key,name:ITEMS[key].name})});return list};
  }

  const priorInventory=inventory;inventory=function(tab="crops"){if(currentMember==="Aida"&&adminProfile?.role==="admin")ensureAdminStock().catch(()=>{});const r=priorInventory(tab);if(tab==="specials")setTimeout(injectUseButtons,0);return r};
  const priorAdminCenter=showAdminCenter;showAdminCenter=async function(){await ensureAdminStock();return priorAdminCenter.apply(this,arguments)};
  let tries=0;const seedTimer=setInterval(()=>{tries++;if(currentMember==="Aida"&&adminProfile?.role==="admin"&&ownState){ensureAdminStock().finally(()=>clearInterval(seedTimer))}else if(tries>50)clearInterval(seedTimer)},500);

  const prevDraw=draw;draw=function(){const r=prevDraw.apply(this,arguments);try{renderDrops()}catch(e){console.warn("V221 render grass",e)}return r};
  const prevReturn=returnFromFriendVisit;returnFromFriendVisit=function(){clearDrops();return prevReturn.apply(this,arguments)};
  const prevVisit=visitFriend;visitFriend=async function(){const r=await prevVisit.apply(this,arguments);setTimeout(()=>{try{renderDrops()}catch(e){console.warn("V221 visit grass",e)}},80);return r};
  window.YAINOO_BUILD="V221-BLACK-ALPACA-GRASS30";
})();


/* ======================================================================
   V223 — ADMIN GLOBAL GIFT PERMISSION FIX
   Scope: gift sending only. Do not touch alpaca/grass/campaign/other systems.

   Why:
   V218 changed "send to everyone" into one multi-user batch that writes
   gifts + every recipient mailbox + adminGiftDeliveries. Firestore rejects
   the whole batch when any one destination is not allowed by current rules.

   Fix:
   Restore the already-supported broadcasts path for global bundle gifts.
   Every member claims the broadcast into their own save, using the existing
   claimBroadcastGift bundle logic. This avoids cross-user mailbox writes and
   the unsupported adminGiftDeliveries collection.
   ====================================================================== */
(function V223_ADMIN_GLOBAL_GIFT_PERMISSION_FIX(){
  sendAdminGlobalBundleGift=async function(catalog){
    if(adminProfile?.role!=="admin")return;
    const btn=$("adminSendGlobalBundleBtn");
    const oldText=btn?.textContent||"ส่งชุดนี้ให้ทุกคน";
    if(btn){btn.disabled=true;btn.textContent="กำลังส่งให้ทุกคน..."}
    try{
      const items=selectedAdminBundle(catalog,"admin-global");
      const includeAida=Boolean($("adminIncludeAida")?.checked);
      if(!items.length)throw new Error("กรุณาติ๊กของอย่างน้อย 1 รายการ");

      /* Validate every item against the same inventory receiver used when a
         member claims the gift. This prevents creating an unclaimable bundle. */
      const sample=normalizeState(cloneData(ownState||state),currentMember||"Aida");
      addGiftItemToState(sample,{items:items.map(i=>({type:i.type,key:i.key,name:i.name,qty:Math.max(1,Math.floor(Number(i.qty)||1))}))});

      const {db,fs}=await getFirebaseContext();
      const cleanItems=items.map(i=>({
        type:i.type,
        key:i.key,
        name:i.name,
        qty:Math.max(1,Math.floor(Number(i.qty)||1))
      }));
      const summary=cleanItems.map(i=>`${i.name} ×${i.qty}`).join(" • ");

      /* Broadcasts is the existing collection already used by Admin notices
         and by the existing member-side broadcast claim flow. */
      const ref=await fs.addDoc(fs.collection(db,"broadcasts"),{
        type:"gift",
        bundle:true,
        items:cleanItems,
        title:"🎁 ของขวัญจากยัยหนู",
        body:summary,
        includeAida,
        from:"Aida",
        deliveryMode:"broadcast-v223",
        createdAt:fs.serverTimestamp()
      });

      /* Verify the document exists before reporting success. */
      const check=await fs.getDoc(ref);
      if(!check.exists())throw new Error("ระบบยังไม่ยืนยันการบันทึกของขวัญ กรุณาลองใหม่");

      showWeatherToast(`🎁 ส่งชุดของขวัญให้ทุกคนสำเร็จแล้ว${includeAida?" • รวม Aida":""}`);
      await showAdminCenter();
    }catch(error){
      message("ส่งของขวัญไม่สำเร็จ",error.message||"กรุณาลองใหม่");
    }finally{
      if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=oldText}
    }
  };

  /* The audit button points to adminGiftDeliveries, the same unsupported
     collection that caused the permission failure. Hide only that button. */
  const previousShowAdminCenter=showAdminCenter;
  showAdminCenter=async function(){
    const result=await previousShowAdminCenter.apply(this,arguments);
    const audit=$("v218GiftAuditBtn");
    if(audit)audit.remove();
    return result;
  };

  window.YAINOO_BUILD="V223-GIFT-PERMISSION-FIX";
  console.info("V223 admin global gift permission fix loaded");
})();

/* V224 — Pink alpaca proportion hotfix.
   Only Pink Idle + Front frame aspect ratio was corrected.
   No movement, shadow, side/back animation, gift, grass, campaign or other system changes. */


/* ======================================================================
   V225 — INDIVIDUAL ADMIN GIFT PERMISSION FIX
   Scope: individual gift delivery only.
   Global gifts remain on the working V223 broadcast path.

   Problem:
   Cross-user writes to mailboxes/<recipient>/items are rejected by current
   Firestore rules. Aida can write broadcasts, and recipients can claim their
   own broadcast claims/save.

   Fix:
   - Individual gifts become TARGETED broadcasts.
   - fetchBroadcasts hides targeted broadcasts from everyone except targetKey.
   - claimBroadcastGift additionally verifies targetKey before granting items.
   ====================================================================== */
(function V225_INDIVIDUAL_GIFT_PERMISSION_FIX(){
  /* Hide targeted broadcasts from non-recipients everywhere that calls
     fetchBroadcasts (notifications, badge, etc.). */
  const V225_fetchBroadcastsBase=fetchBroadcasts;
  fetchBroadcasts=async function(){
    const rows=await V225_fetchBroadcastsBase();
    return rows.filter(b=>!b?.targetKey || String(b.targetKey)===String(currentMemberKey||""));
  };

  /* Bundle gift to one member: use a targeted broadcast instead of
     gifts + cross-user mailbox. */
  sendAdminBundleGift=async function(catalog){
    if(adminProfile?.role!=="admin")return;
    const targetSelect=$("adminBundleTarget");
    const targetKey=String(targetSelect?.value||"");
    const targetName=String(
      targetSelect?.options?.[targetSelect.selectedIndex]?.textContent?.replace(" (ตัวเอง)","") || targetKey
    );
    const items=selectedAdminBundle(catalog,"admin-bundle");

    if(!targetKey){message("ยังส่งไม่ได้","กรุณาเลือกสมาชิก");return}
    if(!items.length){message("ยังส่งไม่ได้","กรุณาติ๊กของอย่างน้อย 1 รายการ");return}

    const btn=$("adminSendBundleBtn");
    const oldText=btn?.textContent||"ส่งให้คนนี้";
    if(btn){btn.disabled=true;btn.textContent="กำลังส่ง..."}

    try{
      const cleanItems=items.map(i=>({
        type:i.type,
        key:i.key,
        name:i.name,
        qty:Math.max(1,Math.floor(Number(i.qty)||1))
      }));

      /* Validate that receiver inventory supports all item types before write. */
      const sample=normalizeState(cloneData(ownState||state),currentMember||"Aida");
      addGiftItemToState(sample,{items:cleanItems});

      const summary=cleanItems.map(i=>`${i.name} ×${i.qty}`).join(" • ");
      const {db,fs}=await getFirebaseContext();

      const ref=await fs.addDoc(fs.collection(db,"broadcasts"),{
        type:"gift",
        bundle:true,
        items:cleanItems,
        title:"🎁 ของขวัญจากยัยหนู",
        body:summary,
        from:"Aida",
        targetKey,
        targetName,
        deliveryMode:"targeted-broadcast-v225",
        createdAt:fs.serverTimestamp()
      });

      const check=await fs.getDoc(ref);
      if(!check.exists())throw new Error("ระบบยังไม่ยืนยันการบันทึกของขวัญ กรุณาลองใหม่");

      showWeatherToast(`🎁 ส่งกล่องให้ ${targetName} สำเร็จแล้ว`);
      await showAdminCenter();
    }catch(error){
      message("ส่งของไม่ได้",error.message||"กรุณาลองใหม่");
    }finally{
      if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=oldText}
    }
  };

  /* Old single-item Admin sender can still be reached by older UI wrappers.
     Route it through the same targeted-broadcast path. */
  sendAdminTargetGift=async function(targetKey,targetName,entry,qty){
    if(!entry||adminProfile?.role!=="admin")return;
    targetKey=String(targetKey||"");
    targetName=String(targetName||targetKey);
    qty=Math.max(1,Math.floor(Number(qty)||1));
    if(!targetKey){message("ยังส่งไม่ได้","กรุณาเลือกสมาชิก");return}

    try{
      const item={type:entry.type,key:entry.key,name:entry.name,qty};
      const sample=normalizeState(cloneData(ownState||state),currentMember||"Aida");
      addGiftItemToState(sample,{items:[item]});

      const {db,fs}=await getFirebaseContext();
      const ref=await fs.addDoc(fs.collection(db,"broadcasts"),{
        type:"gift",
        bundle:true,
        items:[item],
        title:"🎁 ของขวัญจากยัยหนู",
        body:`${entry.name} ×${qty}`,
        from:"Aida",
        targetKey,
        targetName,
        deliveryMode:"targeted-broadcast-v225",
        createdAt:fs.serverTimestamp()
      });
      const check=await fs.getDoc(ref);
      if(!check.exists())throw new Error("ระบบยังไม่ยืนยันการบันทึกของขวัญ กรุณาลองใหม่");

      showWeatherToast(`🎁 ส่ง ${entry.name} ×${qty} ให้ ${targetName} แล้ว`);
      await showAdminCenter();
    }catch(error){
      message("ส่งของไม่ได้",error.message||"กรุณาลองใหม่");
    }
  };

  /* Harden claim: targeted gift can only be claimed by its designated member.
     Keep the existing working bundle/global behavior. */
  claimBroadcastGift=async function(broadcastId,accept){
    try{
      await settlePendingCloudSave();
      const {db,fs}=await getFirebaseContext(),
        broadcastRef=fs.doc(db,"broadcasts",broadcastId),
        claimRef=fs.doc(db,"broadcasts",broadcastId,"claims",currentMemberKey),
        saveRef=fs.doc(db,"saves",currentMemberKey);
      let next;

      await fs.runTransaction(db,async tx=>{
        const [bSnap,cSnap,sSnap]=await Promise.all([
          tx.get(broadcastRef),tx.get(claimRef),tx.get(saveRef)
        ]);
        if(!bSnap.exists()||!sSnap.exists())throw new Error("ไม่พบของขวัญจากยัยหนู");
        if(cSnap.exists())throw new Error("คุณจัดการของขวัญนี้แล้ว");

        const b=bSnap.data();
        if(b.type!=="gift")throw new Error("รายการนี้ไม่ใช่ของขวัญ");
        if(b.targetKey && String(b.targetKey)!==String(currentMemberKey)){
          throw new Error("ของขวัญนี้ไม่ได้ส่งถึงคุณ");
        }
        if(currentMember==="Aida"&&b.includeAida===false){
          throw new Error("ของขวัญรอบนี้ไม่ได้รวม Aida");
        }

        const s=normalizeState(sSnap.data(),currentMember);
        if(accept){
          if(Array.isArray(b.items))addGiftItemToState(s,{items:b.items});
          else addGiftItemToState(s,{itemType:b.itemType,itemKey:b.itemKey,qty:b.qty});
        }
        next=s;

        tx.set(saveRef,{
          ...cloneData(s),
          activeSessionId:cloudSessionId,
          updatedAt:fs.serverTimestamp()
        },{merge:false});

        tx.set(claimRef,{
          memberKey:currentMemberKey,
          status:accept?"accepted":"discarded",
          resolvedAt:fs.serverTimestamp()
        });
      });

      ownState=normalizeState(next,currentMember);
      if(!visitContext)state=ownState;
      saveLocalOnly(ownState);
      updateMeritUI();
      broadcastClaimCache.set(
        broadcastClaimCacheKey(broadcastId),
        {memberKey:currentMemberKey,status:accept?"accepted":"discarded"}
      );
      showNotifications("yainoo");
      showWeatherToast(accept?"🎁 รับของขวัญจากยัยหนูแล้ว":"🗑️ ทิ้งของขวัญแล้ว");
    }catch(error){
      message("จัดการของขวัญไม่ได้",error.message||"กรุณาลองใหม่");
    }
  };

  window.YAINOO_BUILD="V225-INDIVIDUAL-GIFT-PERMISSION-FIX";
  console.info("V225 individual gift permission fix loaded");
})();


/* ======================================================================
   V226 — GIFT SYSTEM CLEANUP
   One runtime path for Admin gifts:
     • one member  -> targeted broadcast
     • everyone    -> global broadcast
     • claim       -> one canonical broadcast claim function
   Friend-to-friend gifts keep the existing gifts/mailbox path.
   No alpaca/grass/campaign/farm changes.
   ====================================================================== */
(function V226_GIFT_SYSTEM_CLEANUP(){
  function V226_cleanBundle(items){
    return (Array.isArray(items)?items:[]).map(i=>({
      type:String(i.type||""),
      key:String(i.key||""),
      name:String(i.name||i.key||"ของขวัญ"),
      qty:Math.max(1,Math.floor(Number(i.qty)||1))
    })).filter(i=>i.type&&i.key);
  }

  function V226_validateBundle(items){
    if(!items.length)throw new Error("กรุณาติ๊กของอย่างน้อย 1 รายการ");
    const sample=normalizeState(cloneData(ownState||state),currentMember||"Aida");
    addGiftItemToState(sample,{items});
  }

  async function V226_writeAdminBroadcast({items,targetKey="",targetName="",includeAida=false}){
    const clean=V226_cleanBundle(items);
    V226_validateBundle(clean);

    const {db,fs}=await getFirebaseContext();
    const summary=clean.map(i=>`${i.name} ×${i.qty}`).join(" • ");

    const payload={
      type:"gift",
      bundle:true,
      items:clean,
      title:"🎁 ของขวัญจากยัยหนู",
      body:summary,
      from:"Aida",
      deliveryMode:targetKey?"targeted-broadcast-v226":"global-broadcast-v226",
      createdAt:fs.serverTimestamp()
    };
    if(targetKey){
      payload.targetKey=String(targetKey);
      payload.targetName=String(targetName||targetKey);
    }else{
      payload.includeAida=Boolean(includeAida);
    }

    const ref=await fs.addDoc(fs.collection(db,"broadcasts"),payload);
    const check=await fs.getDoc(ref);
    if(!check.exists())throw new Error("ระบบยังไม่ยืนยันการบันทึกของขวัญ กรุณาลองใหม่");
    return {id:ref.id,summary,clean};
  }

  /* CANONICAL: Admin bundle -> one member */
  sendAdminBundleGift=async function(catalog){
    if(adminProfile?.role!=="admin")return;
    const targetSelect=$("adminBundleTarget");
    const targetKey=String(targetSelect?.value||"");
    const targetName=String(
      targetSelect?.options?.[targetSelect.selectedIndex]?.textContent?.replace(" (ตัวเอง)","")||targetKey
    );
    if(!targetKey){message("ยังส่งไม่ได้","กรุณาเลือกสมาชิก");return}

    const btn=$("adminSendBundleBtn"),old=btn?.textContent||"ส่งให้คนนี้";
    if(btn){btn.disabled=true;btn.textContent="กำลังส่ง..."}
    try{
      const items=V226_cleanBundle(selectedAdminBundle(catalog,"admin-bundle"));
      await V226_writeAdminBroadcast({items,targetKey,targetName});
      showWeatherToast(`🎁 ส่งกล่องให้ ${targetName} สำเร็จแล้ว`);
      await showAdminCenter();
    }catch(error){
      message("ส่งของไม่ได้",error.message||"กรุณาลองใหม่");
    }finally{
      if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=old}
    }
  };

  /* CANONICAL: Admin bundle -> everyone */
  sendAdminGlobalBundleGift=async function(catalog){
    if(adminProfile?.role!=="admin")return;
    const btn=$("adminSendGlobalBundleBtn"),old=btn?.textContent||"ส่งชุดนี้ให้ทุกคน";
    if(btn){btn.disabled=true;btn.textContent="กำลังส่งให้ทุกคน..."}
    try{
      const items=V226_cleanBundle(selectedAdminBundle(catalog,"admin-global"));
      const includeAida=Boolean($("adminIncludeAida")?.checked);
      await V226_writeAdminBroadcast({items,includeAida});
      showWeatherToast(`🎁 ส่งชุดของขวัญให้ทุกคนสำเร็จแล้ว${includeAida?" • รวม Aida":""}`);
      await showAdminCenter();
    }catch(error){
      message("ส่งของขวัญไม่สำเร็จ",error.message||"กรุณาลองใหม่");
    }finally{
      if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=old}
    }
  };

  /* Compatibility: old one-item Admin UI -> same canonical targeted route */
  sendAdminTargetGift=async function(targetKey,targetName,entry,qty){
    if(!entry||adminProfile?.role!=="admin")return;
    targetKey=String(targetKey||"");
    if(!targetKey){message("ยังส่งไม่ได้","กรุณาเลือกสมาชิก");return}
    try{
      await V226_writeAdminBroadcast({
        items:[{type:entry.type,key:entry.key,name:entry.name,qty}],
        targetKey,
        targetName:String(targetName||targetKey)
      });
      showWeatherToast(`🎁 ส่ง ${entry.name} ×${Math.max(1,Math.floor(Number(qty)||1))} ให้ ${targetName} แล้ว`);
      await showAdminCenter();
    }catch(error){
      message("ส่งของไม่ได้",error.message||"กรุณาลองใหม่");
    }
  };

  /* Compatibility: old one-item global UI -> same canonical global route */
  sendAdminGlobalGift=async function(entry,qty){
    if(!entry||adminProfile?.role!=="admin")return;
    try{
      await V226_writeAdminBroadcast({
        items:[{type:entry.type,key:entry.key,name:entry.name,qty}],
        includeAida:false
      });
      showWeatherToast("🎁 ส่งของขวัญให้ทุกคนแล้ว");
      await showAdminCenter();
    }catch(error){
      message("ส่งของขวัญไม่สำเร็จ",error.message||"กรุณาลองใหม่");
    }
  };

  /* CANONICAL broadcast listing: a targeted gift is visible only to target. */
  const V226_fetchBroadcastsRaw=fetchBroadcasts;
  fetchBroadcasts=async function(){
    const rows=await V226_fetchBroadcastsRaw();
    return rows.filter(b=>{
      if(!b?.targetKey)return true;
      return String(b.targetKey)===String(currentMemberKey||"");
    });
  };

  /* CANONICAL claim for both targeted and global Admin broadcasts.
     R17: use the same save pipeline as ordinary gameplay, because that is the
     path already proven to save correctly for members. No claims subcollection
     and no special gift-only transaction write. */
  claimBroadcastGift=async function(broadcastId,accept){
    try{
      const {db,fs}=await getFirebaseContext();
      const broadcastRef=fs.doc(db,"broadcasts",broadcastId);
      const bSnap=await fs.getDoc(broadcastRef);
      if(!bSnap.exists())throw new Error("ไม่พบของขวัญจากยัยหนู");

      const b=bSnap.data();
      if(b.type!=="gift")throw new Error("รายการนี้ไม่ใช่ของขวัญ");
      if(b.targetKey && String(b.targetKey)!==String(currentMemberKey)){
        throw new Error("ของขวัญนี้ไม่ได้ส่งถึงคุณ");
      }
      if(!b.targetKey && currentMember==="Aida" && b.includeAida===false){
        throw new Error("ของขวัญรอบนี้ไม่ได้รวม Aida");
      }

      const s=normalizeState(cloneData(ownState||state),currentMember);
      s.broadcastGiftClaims=s.broadcastGiftClaims&&typeof s.broadcastGiftClaims==="object"
        ? s.broadcastGiftClaims : {};
      if(s.broadcastGiftClaims[broadcastId])throw new Error("คุณจัดการของขวัญนี้แล้ว");

      if(accept){
        if(Array.isArray(b.items)){
          addGiftItemToState(s,{items:V226_cleanBundle(b.items)});
        }else{
          addGiftItemToState(s,{itemType:b.itemType,itemKey:b.itemKey,qty:b.qty});
        }
      }
      s.broadcastGiftClaims[broadcastId]={
        status:accept?"accepted":"discarded",
        resolvedAt:gameNow()
      };

      ownState=normalizeState(s,currentMember);
      if(!visitContext)state=ownState;
      saveLocalOnly(ownState);
      save();
      await settlePendingCloudSave();

      /* Verify that the normal save pipeline actually persisted this claim. */
      const verify=await fs.getDoc(fs.doc(db,"saves",currentMemberKey));
      const savedClaim=verify.data()?.broadcastGiftClaims?.[broadcastId];
      if(!verify.exists()||!savedClaim)throw new Error("บันทึกการรับของขวัญยังไม่สำเร็จ");

      updateMeritUI();
      try{
        broadcastClaimCache.set(
          broadcastClaimCacheKey(broadcastId),
          {memberKey:currentMemberKey,status:accept?"accepted":"discarded"}
        );
      }catch{}
      await showNotifications("yainoo");
      showWeatherToast(accept?"🎁 รับของขวัญจากยัยหนูแล้ว":"🗑️ ทิ้งของขวัญแล้ว");
    }catch(error){
      message("จัดการของขวัญไม่ได้",error.message||"กรุณาลองใหม่");
    }
  };

  /* Remove only obsolete audit UI that depends on the unsupported
     adminGiftDeliveries collection. */
  const V226_showAdminCenterBase=showAdminCenter;
  showAdminCenter=async function(){
    const result=await V226_showAdminCenterBase.apply(this,arguments);
    const audit=$("v218GiftAuditBtn");
    if(audit)audit.remove();
    return result;
  };

  window.YAINOO_BUILD="V226-GIFT-SYSTEM-CLEANUP";
  console.info("V226 gift system cleanup loaded");
})();


