      content.innerHTML=`<section class="feature-panel alpaca-panel alpaca-confirm-panel"><div class="alpaca-notice-icon" aria-hidden="true">🦙</div><h2>${safeHtml(String(title||"ยืนยัน"))}</h2><div class="alpaca-notice-copy">${String(text||"")}</div><div class="alpaca-detail-actions"><button id="alpacaConfirmYes" class="${danger?"danger":"primary"}" type="button">${safeHtml(confirmText)}</button><button id="alpacaConfirmNo" type="button">${safeHtml(cancelText)}</button></div></section>`;
