  function v240ShowFactoryProductsInventory(){const f=v240FactoryCounts();$("modalContent").innerHTML=`<section class="feature-panel alpaca-panel"><h2>🏭 ผลิตภัณฑ์จากโรงงานแปรรูป</h2><div class="alpaca-inventory-grid">${Object.entries(V240_PRODUCTS).map(([k,r])=>`<article class="alpaca-inventory-item"><img src="${r.image}" alt=""><b>${v240Esc(r.name)}</b><strong>×${v240Int(f.products[k])}</strong></article>`).join("")}</div><button id="v240FactoryInvClose" class="secondary-action">ปิด</button></section>`;openModal();$("v240FactoryInvClose").onclick=closeModal}
  const v240InventoryObserver=new MutationObserver(()=>queueMicrotask(v240BindInventoryEnhancements));if($("modalContent"))v240InventoryObserver.observe($("modalContent"),{childList:true,subtree:true});

  /* ---------- Happiness + factory admin rank ---------- */
  async function v240ShowAlpacaRanks(tab="happiness"){
    if(!v240IsAdmin())return;const cacheKey="yainoo-alpaca-rank-cache-v2";
    const paint=byKey=>{const factory=tab==="factory",rows=Object.keys(MEMBERS).filter(n=>n!=="Aida").map(name=>{const key=memberKeyFromName(name),p=byKey?.[key]||{};return{name,happiness:Number(p.alpacaHappiness)||0,factory:v240Int(p.alpacaFactoryClaimed)}}).sort((a,b)=>(factory?b.factory-a.factory:b.happiness-a.happiness)||a.name.localeCompare(b.name,"th"));$("modalContent").innerHTML=`<section class="feature-panel v240-rank-panel"><header><div><small>🦙 ระบบอัลปาก้า</small><h2>${factory?"Rank แปรรูป":"Rank ความสุข"}</h2></div><button id="v240RankClose">×</button></header><div class="v240-rank-tabs"><button data-v240-rank="happiness" class="${!factory?"active":""}">ความสุข</button><button data-v240-rank="factory" class="${factory?"active":""}">แปรรูป</button></div><div class="v240-rank-scroll">${rows.map((r,i)=>`<article class="v240-rank-row ${i<3?`top${i+1}`:""}"><strong>#${i+1}</strong><div><b>${v240Esc(r.name)}</b><small>${factory?"คะแนนแปรรูป":"คะแนนความสุข"}</small></div><span>${factory?r.factory:r.happiness}</span></article>`).join("")}</div></section>`;openModal();document.querySelectorAll("[data-v240-rank]").forEach(x=>x.onclick=()=>v240ShowAlpacaRanks(x.dataset.v240Rank));$("v240RankClose").onclick=closeModal};
    let cached={};try{cached=JSON.parse(localStorage.getItem(cacheKey)||"{}")||{}}catch{}paint(cached);if(!cloudReady)return;
    try{const {db,fs}=await getFirebaseContext(),snap=await Promise.race([fs.getDocs(fs.collection(db,"publicProfiles")),new Promise((_,rej)=>setTimeout(()=>rej(new Error("rank-timeout")),3000))]),byKey={};snap.forEach(d=>byKey[d.id]=d.data());localStorage.setItem(cacheKey,JSON.stringify(byKey));paint(byKey)}catch(e){console.warn("alpaca rank refresh",e)}
  }

  /* ---------- Rainbow fish ---------- */
  const V240_RAINBOW={fishKey:"rainbow5",name:"ปลาสายรุ้ง พี่ไม่ปลื้ม",image:"fishing-fish-rainbow-tier5.png?v=240",tier:5,min:8,max:12};
  try{FISHING_FISH[V240_RAINBOW.fishKey]={name:V240_RAINBOW.name,image:V240_RAINBOW.image,tier:5,min:8,max:12}}catch{}
  const v240RollFishBase=rollFishingCatches;
  rollFishingCatches=function(baitKey){const base=v240RollFishBase(baitKey),chance={bait1:.80,bait2:.90,bait3:.20,bait4:.25,guardian:0,guardianBait:0}[baitKey]??0;if(chance<=0||Math.random()>=chance)return base;const count=Math.random()<.22?2:1;/* rainbow-specific double; existing fish count distribution remains untouched */const rainbow=Array.from({length:count},()=>({fishKey:V240_RAINBOW.fishKey,name:V240_RAINBOW.name,image:V240_RAINBOW.image,weight:Number((8+Math.random()*4).toFixed(2))}));const keep=(base.catches||[]).filter(c=>c.fishKey!==V240_RAINBOW.fishKey);const catches=[...rainbow,...keep].slice(0,3),total=Number(catches.reduce((n,c)=>n+Number(c.weight||0),0).toFixed(2));return{catches,total}};

  async function Y24_recordRainbowCampaign(slot,receiptOverride=""){try{const rainbow=(slot?.catches||[]).filter(c=>c.fishKey===V240_RAINBOW.fishKey||c.name===V240_RAINBOW.name).length;if(!rainbow)return;const receipt=receiptOverride||`${slot.dateKey||currentBangkokDateKey()}:${slot.pondId||0}:${slot.slot||0}:${slot.startedAt||slot.finishAt||0}`;await v240AddCampaignScore(V240_RAINBOW_ID,rainbow,{receipt})}catch(e){console.warn("rainbow campaign score",e)}}
  globalThis.Y24_recordRainbowCampaign=Y24_recordRainbowCampaign;

  /* Attach campaign scoring to the final fish-claim button without changing fishing ownership/storage semantics. */
  const v240OpenModalBase=openModal;
  openModal=function(){const r=v240OpenModalBase();queueMicrotask(()=>{const btn=$("ynuClaimFish");if(btn&&!btn.__v240Rainbow){const cards=[...document.querySelectorAll("#modalContent .fishing-result-card")],count=cards.filter(c=>c.textContent.includes(V240_RAINBOW.name)).length,old=btn.onclick;btn.onclick=async ev=>{const before=Object.keys((ownState||state)?.fishingClaimReceipts||{}).length;const ret=await old?.call(btn,ev);setTimeout(async()=>{const afterState=normalizeState(ownState||state,currentMember),receipts=afterState.fishingClaimReceipts||{},keys=Object.keys(receipts);if(count>0&&keys.length>before){const receipt=keys.sort((a,b)=>Number(receipts[b])-Number(receipts[a]))[0];await v240AddCampaignScore(V240_RAINBOW_ID,count,{receipt}).catch(console.warn)}},120);return ret};btn.__v240Rainbow=true}});return r};

  /* ---------- Campaign score core ---------- */
  async function v240AddCampaignScore(campaignId,amount,{night=0,receipt=""}={}){
    if(!cloudReady||!currentMemberKey||currentMember==="Aida")return;
    amount=Math.max(0,Math.floor(Number(amount)||0));if(!amount)return;
    const cfg=campaignId===V240_COOK_ID?V240_CAMPAIGNS.cooking:V240_CAMPAIGNS.rainbow;if(v240Now()>cfg.endAt)return;
    if(!receipt){
      return window.YN_R7_campaignIncrement(campaignId,amount,{night});
    }
    const {db,fs}=await getFirebaseContext(),saveRef=fs.doc(db,"saves",currentMemberKey),scoreRef=fs.doc(db,"campaignScores",campaignId);let next=null;
    await fs.runTransaction(db,async tx=>{
      const [sv,sc]=await Promise.all([tx.get(saveRef),tx.get(scoreRef)]);if(!sv.exists())throw new Error("ไม่พบเซฟสมาชิก");
      const st=normalizeState(sv.data(),currentMember);assertCurrentCloudSession(sv.data(),currentMember);
      st.campaignReceipts=v240Obj(st.campaignReceipts);const rk=`${campaignId}:${receipt}`;if(st.campaignReceipts[rk])return;
      st.campaignReceipts[rk]=v240Now();
      tx.set(saveRef,{...cloneData(st),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
      if(sc.exists()){
        const patch={campaignId,[`scores.${currentMemberKey}`]:fs.increment(amount),[`names.${currentMemberKey}`]:currentProfileDisplayName(),updatedAt:fs.serverTimestamp()};
        if(night)patch[`nightCounts.${currentMemberKey}`]=fs.increment(Math.max(0,Math.floor(Number(night)||0)));
        tx.update(scoreRef,patch);
      }else{
        tx.set(scoreRef,{campaignId,scores:{[currentMemberKey]:amount},names:{[currentMemberKey]:currentProfileDisplayName()},...(night?{nightCounts:{[currentMemberKey]:Math.max(0,Math.floor(Number(night)||0))}}:{}),updatedAt:fs.serverTimestamp()},{merge:false});
      }
      next=st;
    });
    if(next)v240Apply(next);
  }

  const V240_GENERAL_IDS=new Set(["r1","r2","r3","r4","r5","r6","r7","r8","rabbitMenu1","rabbitMenu2","rabbitMenu3","rabbitMenu4","rabbitMenu5","rabbitMenu6"]);
  const V240_NIGHT_IDS=new Set(["n1","n2","n3","n4"]),V240_SPECIAL_IDS=new Set(["boatNew1","boatNew2","boatNew3","boatNew4","boatNew5","boatNew6","boatNew7","boatNew8"]);
  function v240DishCount(s,id){try{return typeof dishCountInState==="function"?dishCountInState(id,s):v240Int(s?.dishInventory?.[id]||s?.dishes?.[id])}catch{return 0}}
  const v240CraftBase=craft;
  /* The active craft() implementation is async.  The old wrapper checked the
     inventory before the Promise finished, so successful crafts looked like
     failures to the campaign scorer.  Await the real craft first, then compare. */
  craft=async function(id){
    const before=v240DishCount(ownState||state,id);
    const r=await v240CraftBase(id);
    const after=v240DishCount(ownState||state,id);
    if(after>before){
      const pts=V240_NIGHT_IDS.has(id)?7:V240_SPECIAL_IDS.has(id)?3:V240_GENERAL_IDS.has(id)?1:1;
      /* dailyCraftFood is already persisted by the canonical craft transaction. */
      await v240AddCampaignScore(V240_COOK_ID,pts,{night:V240_NIGHT_IDS.has(id)?1:0})
        .catch(e=>console.warn("cooking campaign score",e));
    }
    return r;
  };
  if(typeof craftBoatDrink==="function"){
    const b=craftBoatDrink;craftBoatDrink=async function(id){
      const target=ownState||state,before=v240Int(target?.boatDrinks?.[id]),r=await b(id),after=v240Int((ownState||state)?.boatDrinks?.[id]);
      if(after>before){await v240AddCampaignScore(V240_COOK_ID,2).catch(e=>console.warn("cooking drink score",e))}
      return r;
    }
  }
  if(typeof craftRainyMenu==="function"){
    const b=craftRainyMenu;craftRainyMenu=async function(id){
      /* R13: score from the canonical Firestore craft transaction result.
         Do not infer success from local inventory deltas; local state may be
         stale and can make a real successful craft score 0. */
      const r=await b(id);
      if(r?.success===true&&!r?.campaignScored){
        await v240AddCampaignScore(V240_COOK_ID,4)
          .catch(e=>{console.error("cooking rainy score fallback",e);try{showWeatherToast(`🌧️ คราฟสำเร็จ แต่คะแนนหน้าฝนยังไม่เข้า: ${e?.message||"Firebase ปฏิเสธ"}`)}catch{}});
      }
      return r;
    }
  }

