/* ======================================================================
   V277 — RESPONSIVE TAP + PERFORMANCE HOTFIX
   - Larger/easier friend-grass hit target and immediate tap feedback
   - Grass inventory confirmation no longer waits for ranking write
   - Mystery-box buttons show busy state immediately and recover on error
   - Avoid hidden alpaca/wild DOM rerenders; adaptive sprite tick on low-core phones
   - No changes to mushroom/steak asset mapping
   ====================================================================== */
/* Fast visual acknowledgement for high-frequency actions. This never changes inventory/state;
   it only makes taps feel immediate while the existing Firebase transaction completes. */
(function V277_FAST_ACTION_FEEDBACK(){
  const selector=[
    "[data-jelly-food]","[data-j2-v1-food]","[data-j2-v2]",
    "[data-yn-pet-feed-key]","[data-y26-feed-dog-plant]",
    "#feedPandaBtn","#j2FeedV1","#j2FeedV2",
    "#feedJellyBtn","#openJellyBoxBtn","#openCatBoxBtn","#openDogBoxBtn"
  ].join(",");
  document.addEventListener("pointerdown",e=>{const b=e.target?.closest?.(selector);if(!b||b.disabled)return;b.classList.add("fast-action-pressed")},{passive:true});
  document.addEventListener("pointerup",e=>{const b=e.target?.closest?.(selector);if(!b)return;setTimeout(()=>b.classList.remove("fast-action-pressed"),90)},{passive:true});
  document.addEventListener("pointercancel",e=>{const b=e.target?.closest?.(selector);b?.classList?.remove("fast-action-pressed")},{passive:true});
})();




