/* =====================================================================
   SEASON 2 V002 — DYNAMIC MEMBERS / APPROVAL / TOP SPENDERS
   - One login surface for legacy + new approved players
   - New player signup -> pending -> Aida/Admin approval
   - Approved names appear automatically without editing game files
   - Legacy Season 1 saves stay on their existing memberKey
   - Top Spenders is live Firestore data; members read, Admin edits
   ===================================================================== */
(function YN_SEASON2_V002_MEMBER_SYSTEM(){
  const LEGACY_CODES={...MEMBERS};
  const S2_DYNAMIC_KEYS=Object.create(null);
  const S2_DYNAMIC_NAMES=Object.create(null);
  const DYNAMIC_SENTINEL="__S2_DYNAMIC__";
  const originalMemberKeyFromName=memberKeyFromName;
  const originalMemberEmailFromName=memberEmailFromName;

  function s2Esc(x){return typeof safeHtml==="function"?safeHtml(String(x??"")):String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
  function s2MemberEmail(memberKey){return `member-${memberKey}@${MEMBER_EMAIL_DOMAIN}`}
  function s2RandomKey(){
    try{const a=new Uint32Array(3);crypto.getRandomValues(a);return "s2-"+Array.from(a,x=>x.toString(36)).join("").slice(0,18)}catch{return "s2-"+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
  }
  function isDynamicName(name){return MEMBERS[name]===DYNAMIC_SENTINEL&&Boolean(S2_DYNAMIC_KEYS[name])}

  memberKeyFromName=function(name){return S2_DYNAMIC_KEYS[name]||originalMemberKeyFromName(name)};
  memberEmailFromName=function(name){return S2_DYNAMIC_KEYS[name]?s2MemberEmail(S2_DYNAMIC_KEYS[name]):originalMemberEmailFromName(name)};

  async function fetchDirectory(){
    try{
      const bridge=await getFirebaseBridge();if(!bridge)return [];
      const {db,firestore:fs}=bridge,snap=await fs.getDocs(fs.collection(db,"loginDirectory")),rows=[];
      snap.forEach(d=>{const x=d.data()||{};if(x.status==="approved"&&x.displayName&&x.memberKey)rows.push({displayName:String(x.displayName),memberKey:String(x.memberKey)})});
      return rows.sort((a,b)=>a.displayName.localeCompare(b.displayName,"th"));
    }catch(e){console.warn("S2 directory",e);return []}
  }
  async function refreshLoginDirectory(){
    const rows=await fetchDirectory();
    Object.keys(MEMBERS).forEach(n=>{if(MEMBERS[n]===DYNAMIC_SENTINEL)delete MEMBERS[n]});
    Object.keys(S2_DYNAMIC_KEYS).forEach(k=>delete S2_DYNAMIC_KEYS[k]);Object.keys(S2_DYNAMIC_NAMES).forEach(k=>delete S2_DYNAMIC_NAMES[k]);
    for(const row of rows){if(LEGACY_CODES[row.displayName])continue;MEMBERS[row.displayName]=DYNAMIC_SENTINEL;S2_DYNAMIC_KEYS[row.displayName]=row.memberKey;S2_DYNAMIC_NAMES[row.memberKey]=row.displayName}
    const select=$("memberSelect");if(!select)return;
    const previous=select.value;
    const names=Object.keys(MEMBERS);
    const admins=names.filter(name=>name==="Aida");
    const players=names.filter(name=>name!=="Aida").sort((a,b)=>a.localeCompare(b,"th"));
    select.innerHTML='<option value="" selected disabled>เลือกชื่อผู้เล่น</option>'
      +(admins.length?`<optgroup label="ผู้ดูแลระบบ">${admins.map(name=>`<option value="${s2Esc(name)}">${s2Esc(name)}</option>`).join("")}</optgroup>`:"")
      +(players.length?`<optgroup label="ผู้เล่น">${players.map(name=>`<option value="${s2Esc(name)}">${s2Esc(name)}</option>`).join("")}</optgroup>`:"");
    if(previous&&Object.prototype.hasOwnProperty.call(MEMBERS,previous))select.value=previous;
  }

  async function dynamicLogin(member,code){
    const key=S2_DYNAMIC_KEYS[member];if(!key)throw new Error("ไม่พบบัญชีที่อนุมัติแล้ว");
    const bridge=await getFirebaseBridge();if(!bridge)throw new Error("Firebase ยังไม่พร้อม");
    let user=bridge.getCurrentUser();const email=s2MemberEmail(key);
    if(user&&String(user.email||"").toLowerCase()!==email.toLowerCase()){await bridge.signOut();user=null}
    if(!user)user=await bridge.signIn(email,code);
    /* Fast path: a forced ID-token refresh is unnecessary here because approval/role
       is read from Firestore by UID. This removes a network round trip on every login. */
    const profile=await bridge.getSignedInMember();
    if(!profile)throw new Error("บัญชีนี้ยังไม่ได้รับการอนุมัติจากแอดมิน");
    if(profile.role!=="member"||profile.status!=="approved"||profile.memberKey!==key)throw new Error("บัญชีนี้ยังไม่ได้รับการอนุมัติจากแอดมิน");
    return {user,profile,key};
  }

  const previousStart=start;
  start=async function(){
    const member=$("memberSelect")?.value||"",code=$("memberCode")?.value.trim()||"";
    if(!member){$("loginError").textContent="กรุณาเลือกชื่อผู้เล่นก่อนค่ะ";return}
    if(!code){$("loginError").textContent="กรุณากรอกรหัสผ่านค่ะ";return}
    if(MAINTENANCE_MODE&&member!==MAINTENANCE_ADMIN_MEMBER){$("loginError").textContent="🔧 ขออภัย กำลังปิดปรับปรุงระบบ • เตรียมพบกับ Season ใหม่เร็ว ๆ นี้ค่ะ";return}
    if(!isDynamicName(member))return previousStart();
    try{
      const loginBtn=$("startBtn");if(loginBtn){loginBtn.disabled=true;loginBtn.textContent="กำลังเข้าสวน..."}
      stopOnlineListeners();cloudReady=false;adminProfile=null;visitContext=null;currentMember=member;currentMemberKey=S2_DYNAMIC_KEYS[member];ownState=fresh(member);state=ownState;$("loginError").textContent="กำลังโหลดข้อมูล...";
      await dynamicLogin(member,code);await initializeOrLoadCloudState(member,currentMemberKey);enterGameScreen();showWeatherToast("☁️ โหลดเซฟส่วนกลางแล้ว");
    }catch(error){console.error("S2 login",error);currentMember=null;currentMemberKey="";ownState=state=null;$("loginError").textContent=error?.code==="auth/invalid-credential"?"ชื่อผู้เล่นหรือรหัสผ่านไม่ถูกต้อง":String(error.message||"เข้าสู่ระบบไม่สำเร็จ")}
    finally{const loginBtn=$("startBtn");if(loginBtn){loginBtn.disabled=false;loginBtn.textContent="เข้าสู่สวน"}}
  };

  function signupTermsHTML(){return `<div class="s2-terms"><b>เงื่อนไขการสมัคร</b><ol><li>1 คนต่อ 1 บัญชี ห้ามสมัครหลายบัญชีเพื่อรับสิทธิ์หรือรางวัลซ้ำ</li><li>ห้ามใช้ชื่อเลียนแบบสมาชิกเดิม แอดมิน หรือชื่อที่ไม่เหมาะสม</li><li>ห้ามใช้บั๊ก โปรแกรมช่วยเล่น หรือแก้ไขข้อมูลเพื่อเอาเปรียบผู้เล่นอื่น</li><li>ห้ามซื้อขาย/แลกเปลี่ยนบัญชี หรือขอรหัสผ่านของผู้เล่นอื่น</li><li>ห้ามคุกคาม รบกวน หรือสร้างปัญหาให้ผู้เล่นอื่น</li><li>หากพบข้อผิดพลาด กรุณาแจ้งแอดมินและห้ามนำบั๊กไปใช้หาผลประโยชน์</li><li>บัญชีใหม่ต้องได้รับการอนุมัติจากแอดมินก่อนเข้าเล่น</li><li>แอดมินสามารถระงับหรือยกเลิกบัญชีที่ฝ่าฝืนกติกาได้</li><li>กติกาและระบบเกมอาจปรับเปลี่ยนตามความเหมาะสมของแต่ละ Season</li></ol></div>`}
  function showSignup(){
    $("modalContent").innerHTML=`<section class="feature-panel s2-signup-panel"><h2>🌱 สมัครสมาชิก</h2><p class="feature-subtitle">สมัครแล้วรอ Aida อนุมัติก่อนเข้าเล่นค่ะ</p><div class="s2-form-grid"><label>ชื่อผู้เล่น<input id="s2SignupName" maxlength="16" autocomplete="nickname" placeholder="2–16 ตัวอักษร"></label><label>รหัสผ่าน<input id="s2SignupPass" type="password" minlength="6" maxlength="32" autocomplete="new-password" placeholder="อย่างน้อย 6 ตัว"></label><label>ยืนยันรหัสผ่าน<input id="s2SignupPass2" type="password" minlength="6" maxlength="32" autocomplete="new-password" placeholder="พิมพ์รหัสอีกครั้ง"></label>${signupTermsHTML()}<label class="s2-terms-check"><input id="s2TermsAccept" type="checkbox"><span>ฉันอ่านและยอมรับเงื่อนไขการสมัครแล้ว</span></label><button id="s2SubmitSignup" class="primary-spooky-action" type="button">ส่งคำขอสมัคร</button><p id="s2SignupStatus"></p></div></section>`;openModal();$("s2SubmitSignup").onclick=submitSignup;
  }
  async function submitSignup(){
    const name=$("s2SignupName")?.value.trim()||"",pass=$("s2SignupPass")?.value||"",pass2=$("s2SignupPass2")?.value||"",status=$("s2SignupStatus"),btn=$("s2SubmitSignup");
    if(name.length<2||name.length>16){status.textContent="ชื่อผู้เล่นต้องยาว 2–16 ตัวอักษร";return}if(LEGACY_CODES[name]||S2_DYNAMIC_KEYS[name]){status.textContent="ชื่อนี้มีผู้ใช้อยู่แล้วค่ะ";return}if(pass.length<6){status.textContent="รหัสผ่านต้องมีอย่างน้อย 6 ตัว";return}if(pass!==pass2){status.textContent="รหัสผ่านสองช่องไม่ตรงกัน";return}if(!$("s2TermsAccept")?.checked){status.textContent="กรุณายอมรับเงื่อนไขก่อนสมัคร";return}
    btn.disabled=true;status.textContent="กำลังส่งคำขอ...";
    try{
      const bridge=await getFirebaseBridge();if(!bridge)throw new Error("Firebase ยังไม่พร้อม");
      if(bridge.getCurrentUser())await bridge.signOut();
      const memberKey=s2RandomKey(),email=s2MemberEmail(memberKey),user=await bridge.signInOrCreate(email,pass),{db,firestore:fs}=bridge;
      await fs.setDoc(fs.doc(db,"membershipApplications",user.uid),{uid:user.uid,displayName:name,memberKey,email,status:"pending",acceptedTerms:true,createdAt:fs.serverTimestamp()},{merge:false});
      await bridge.signOut();
      $("modalContent").innerHTML=`<section class="feature-panel s2-application-panel"><h2>✅ ส่งคำขอแล้ว</h2><p><b>${s2Esc(name)}</b></p><p>กรุณารอ Aida อนุมัติค่ะ<br>เมื่ออนุมัติแล้วชื่อของคุณจะขึ้นในช่อง <b>เลือกชื่อผู้เล่น</b> อัตโนมัติ</p><button id="s2SignupDone" class="primary-spooky-action">รับทราบ</button></section>`;$("s2SignupDone").onclick=closeModal;
    }catch(e){console.error("S2 signup",e);try{(await getFirebaseBridge())?.signOut()}catch{};btn.disabled=false;status.textContent=String(e.message||"สมัครไม่สำเร็จ")}
  }

  async function pendingApplications(){
    const {db,fs}=await getFirebaseContext(),snap=await fs.getDocs(fs.query(fs.collection(db,"membershipApplications"),fs.where("status","==","pending"))),rows=[];snap.forEach(d=>rows.push({id:d.id,...d.data()}));return rows.sort((a,b)=>timestampMillis(a.createdAt)-timestampMillis(b.createdAt));
  }
  async function approveApplication(id,approve){
    if(adminProfile?.role!=="admin")return;
    try{
      const {db,fs}=await getFirebaseContext(),ref=fs.doc(db,"membershipApplications",id),snap=await fs.getDoc(ref);if(!snap.exists())throw new Error("ไม่พบคำขอ");const a=snap.data();
      if(a.status!=="pending")throw new Error("คำขอนี้ถูกจัดการแล้ว");
      const batch=fs.writeBatch(db);
      if(approve){
        batch.set(fs.doc(db,"members",id),{memberKey:a.memberKey,displayName:a.displayName,role:"member",status:"approved",welcomeGiftClaimed:false,approvedAt:fs.serverTimestamp(),approvedBy:"Aida"},{merge:true});
        batch.set(fs.doc(db,"loginDirectory",a.memberKey),{memberKey:a.memberKey,displayName:a.displayName,status:"approved",approvedAt:fs.serverTimestamp()},{merge:false});
      }
      batch.set(ref,{status:approve?"approved":"rejected",resolvedAt:fs.serverTimestamp(),resolvedBy:"Aida"},{merge:true});await batch.commit();await refreshLoginDirectory();showWeatherToast(approve?`✅ อนุมัติ ${a.displayName} แล้ว`:`❌ ปฏิเสธ ${a.displayName} แล้ว`);notificationBadgeLastAt=0;refreshNotificationBadge(true);showAdminCenter();
    }catch(e){message("จัดการคำขอไม่ได้",e.message||"กรุณาลองใหม่")}
  }

  async function allLoginNames(){
    await refreshLoginDirectory();return Object.keys(MEMBERS).filter(n=>n!=="Aida").sort((a,b)=>a.localeCompare(b,"th"));
  }
  async function loadSpenders(){
    try{const {db,fs}=await getFirebaseContext(),snap=await fs.getDoc(fs.doc(db,"shared","topSpenders"));return snap.exists()?snap.data():{rows:[],updatedAt:null}}catch{return {rows:[],updatedAt:null}}
  }
  async function showTopSpenders(){
    try{
      const data=await loadSpenders(),rows=Array.isArray(data.rows)?data.rows.slice():[];rows.sort((a,b)=>(Number(b.total)||0)-(Number(a.total)||0)||(Number(b.today)||0)-(Number(a.today)||0));
      $("modalContent").innerHTML=`<section class="feature-panel s2-spenders-panel"><header class="s2-spenders-head"><div><small>SEASON 2</small><h2>💎 Top Spenders</h2></div><span>อัปเดตโดย Aida</span></header><div class="s2-spenders-columns"><span>อันดับ / ผู้เล่น</span><span>วันนี้</span><span>สะสม</span></div><div class="s2-spenders-list">${rows.length?rows.map((r,i)=>`<article class="s2-spender-row ${i<3?`top${i+1}`:""}"><span class="s2-spender-rank">${i<3?["🥇","🥈","🥉"][i]:`#${i+1}`}</span><b>${s2Esc(r.name)}</b><small>${Number(r.today||0).toLocaleString()}</small><strong>${Number(r.total||0).toLocaleString()}</strong></article>`).join(""):'<p class="empty-feature">ยังไม่มีข้อมูล Top Spenders</p>'}</div>${adminProfile?.role==="admin"?'<button id="s2EditSpenders" class="s2-spenders-edit-btn" type="button">✏️ แก้ไขข้อมูล</button>':""}</section>`;openModal();if($("s2EditSpenders"))$("s2EditSpenders").onclick=editTopSpenders;
    }catch(e){message("เปิด Top Spenders ไม่ได้",e.message||"กรุณาลองใหม่")}
  }
  async function editTopSpenders(){
    const [names,data]=await Promise.all([allLoginNames(),loadSpenders()]),byName=new Map((Array.isArray(data.rows)?data.rows:[]).map(r=>[String(r.name),r]));
    $("modalContent").innerHTML=`<section class="feature-panel s2-spenders-panel"><h2>✏️ แก้ Top Spenders</h2><p class="feature-subtitle">แก้แล้วกดบันทึกครั้งเดียว ทุกคนจะเห็นข้อมูลล่าสุด</p><div class="s2-editor-head"><span>ผู้เล่น</span><span>วันนี้</span><span>สะสม</span></div><div class="s2-spender-editor">${names.map(name=>{const r=byName.get(name)||{};return `<label class="s2-spender-edit-row"><b>${s2Esc(name)}</b><input type="number" min="0" value="${Math.max(0,Number(r.today)||0)}" data-s2-spend-today="${s2Esc(name)}"><input type="number" min="0" value="${Math.max(0,Number(r.total)||0)}" data-s2-spend-total="${s2Esc(name)}"></label>`}).join("")}</div><button id="s2SaveSpenders" class="primary-spooky-action" type="button">บันทึก</button></section>`;openModal();$("s2SaveSpenders").onclick=saveTopSpenders;
  }
  async function saveTopSpenders(){
    if(adminProfile?.role!=="admin")return;const btn=$("s2SaveSpenders");btn.disabled=true;
    try{const rows=[];document.querySelectorAll("[data-s2-spend-today]").forEach(i=>{const name=i.dataset.s2SpendToday,totalInput=document.querySelector(`[data-s2-spend-total="${CSS.escape(name)}"]`),today=Math.max(0,Math.floor(Number(i.value)||0)),total=Math.max(0,Math.floor(Number(totalInput?.value)||0));if(today||total)rows.push({name,today,total})});const {db,fs}=await getFirebaseContext();await fs.setDoc(fs.doc(db,"shared","topSpenders"),{rows,updatedAt:fs.serverTimestamp(),updatedBy:"Aida"},{merge:false});showWeatherToast("💎 บันทึก Top Spenders แล้ว");showTopSpenders()}catch(e){btn.disabled=false;message("บันทึกไม่ได้",e.message||"กรุณาลองใหม่")}
  }

  const S2_SEASON1_FALLBACK=[
    {name:"Earn Pilaiwan",merit:369245},
    {name:"Porpla Napassorn",merit:359478},
    {name:"ของขวัญ บิวตี้ช้อป",merit:341610},
    {name:"Mhai Maneetanawat",merit:245472},
    {name:"Pukkie F",merit:232609}
  ];
  async function showSeason1ResultsLive(){
    /* Season 1 is public history. Use the fixed final Top 5 immediately;
       a Firestore record may override it later without requiring a code update. */
    let rows=S2_SEASON1_FALLBACK.map(r=>({...r}));
    try{
      const bridge=await getFirebaseBridge();if(bridge){const {db,firestore:fs}=bridge,snap=await fs.getDoc(fs.doc(db,"shared","season1Results"));if(snap.exists()&&Array.isArray(snap.data().rows)&&snap.data().rows.length)rows=snap.data().rows.slice()}
    }catch(e){console.warn("S2 season1 results fallback",e)}
    rows.sort((a,b)=>(Number(b.merit)||0)-(Number(a.merit)||0));
    const html=rows.map((r,i)=>`<article class="s2-season1-row ${i<3?`top top-${i+1}`:""}"><span class="s2-season1-rank">${i<3?["🥇","🥈","🥉"][i]:i+1}</span><div><b>${s2Esc(r.name)}</b><small>คะแนนกุศล</small></div><strong>${Number(r.merit||0).toLocaleString()}</strong></article>`).join("");
    $("modalContent").innerHTML=`<section class="feature-panel s2-season1-panel"><header><small>HALL OF FAME</small><h2>🏆 ผลงานซีซั่น 1</h2><p>Top 5 คะแนนกุศลจากซีซั่นแรก</p></header><div class="s2-season1-list">${html}</div></section>`;openModal();
  }

  const previousAdminCenter=showAdminCenter;
  showAdminCenter=async function(){
    await previousAdminCenter();if(adminProfile?.role!=="admin")return;
    try{const apps=await pendingApplications(),panel=document.querySelector(".admin-panel");if(!panel)return;panel.insertAdjacentHTML("afterbegin",`<div class="admin-section"><h3>🌱 คำขอสมัครสมาชิก (${apps.length})</h3><div class="admin-request-list">${apps.length?apps.map(a=>`<div class="s2-app-card"><b>${s2Esc(a.displayName)}</b><small>รออนุมัติ • ${s2Esc(a.memberKey)}</small><div class="actions"><button type="button" data-s2-approve="${a.id}">อนุมัติ</button><button type="button" data-s2-reject="${a.id}">ปฏิเสธ</button></div></div>`).join(""):'<p class="empty-feature">ไม่มีคำขอสมัครค้าง</p>'}</div></div>`);document.querySelectorAll("[data-s2-approve]").forEach(b=>b.onclick=()=>approveApplication(b.dataset.s2Approve,true));document.querySelectorAll("[data-s2-reject]").forEach(b=>b.onclick=()=>approveApplication(b.dataset.s2Reject,false))}catch(e){console.warn("S2 admin applications",e)}
  };

  const signupBtn=$("season2SignupBtn");if(signupBtn)signupBtn.onclick=showSignup;
  const resultsBtn=$("season1ResultsBtn");if(resultsBtn)resultsBtn.onclick=showSeason1ResultsLive;
  const spendBtn=$("shortcutTopSpendersBtn");if(spendBtn)spendBtn.onclick=()=>{try{$("hudMenuDrawer")?.classList.add("hidden");$("hudMenuBackdrop")?.classList.add("hidden")}catch{}showTopSpenders()};
  const startBtn=$("startBtn");if(startBtn)startBtn.onclick=start;
  window.YN_S2_REFRESH_DIRECTORY=refreshLoginDirectory;
  refreshLoginDirectory();
  /* Directory already loads once at startup; avoid a duplicate network request during login. */
  window.YAINOO_BUILD="S2V006-SEASON1-LOGIN-GROUPS";
  console.info("Season 2 V006 season1 results + grouped login loaded");
})();
(function YN_S2V004_DIRECTORY_RETRY(){
  const retry=()=>{try{const btn=document.getElementById("startBtn");if(btn&&typeof start==="function")btn.onclick=start}catch{}};
  setTimeout(retry,250);setTimeout(retry,1200);
})();

/* ======================================================================
   SEASON 2 • ALPACA PEN V001
   Five pens / 16-slot side troughs / 8h broken-pen repair / new scene hooks.
   ====================================================================== */
(function YN_S2_ALPACA_PEN_V001(){
  "use strict";
  const HOUR=60*60*1000, BREAK_MS=8*HOUR;
  const MATERIALS={
    materialStone:{name:"หิน",image:"item-stone.png",need:100},
    materialWood:{name:"ไม้",image:"item-wood.png",need:100},
    materialSteel:{name:"เหล็ก",image:"item-steel.png",need:50},
    materialRope:{name:"เชือก",image:"item-rope.png",need:50}
  };
  const isS2Admin=()=>currentMember==="Aida"&&adminProfile?.role==="admin";
  const int=x=>Math.max(0,Math.floor(Number(x)||0));
  const activeState=()=>ownState||state;
  const currentPenNo=()=>{const raw=$("alpacaPenStage")?.style?.getPropertyValue("--alpaca-pen-bg")||"";const m=String(raw).match(/alpaca-pen-(\d+)/);return Math.max(1,Math.min(5,Number(m?.[1])||1))};
  const applyState=s=>{ownState=normalizeState(s,currentMember);if(!visitContext)state=ownState;try{saveLocalOnly(ownState)}catch{}};

  /* Existing saves migrate safely: keep pens 1-3, add pens 4-5, expand each trough to 16. */
  const normalizeBase=normalizeState;
  normalizeState=function(raw,player){
    const s=normalizeBase(raw,player);s.specials=s.specials&&typeof s.specials==="object"?s.specials:{};
    Object.keys(MATERIALS).forEach(k=>s.specials[k]=int(s.specials[k]));
    if(isS2Admin())Object.keys(MATERIALS).forEach(k=>s.specials[k]=9999);
    if(s.alpaca&&Array.isArray(s.alpaca.pens)){
      while(s.alpaca.pens.length<5)s.alpaca.pens.push({name:`คอกอัลปาก้า ${s.alpaca.pens.length+1}`,happiness:0,happinessMedicineUses:0,trough:Array(16).fill(null),alpacas:[],events:[],eventClock:{}});
      s.alpaca.pens=s.alpaca.pens.slice(0,5).map((p,i)=>{p=p&&typeof p==="object"?p:{};p.name=String(p.name||`คอกอัลปาก้า ${i+1}`);p.trough=Array.isArray(p.trough)?p.trough.slice(0,16):[];while(p.trough.length<16)p.trough.push(null);if(!Number.isFinite(Number(p.lastVisitedAt)))p.lastVisitedAt=gameNow();p.lastVisitedAt=Number(p.lastVisitedAt)||gameNow();p.broken=Boolean(p.broken);return p});
    }
    return s;
  };
  try{if(ownState)applyState(ownState);if(state&&!ownState)state=normalizeState(state,currentMember)}catch(e){console.warn("S2 alpaca migration",e)}

  try{
    Object.entries(MATERIALS).forEach(([key,m])=>{if(typeof SPECIAL_ITEMS==="object"&&!SPECIAL_ITEMS[key])SPECIAL_ITEMS[key]={name:m.name,image:m.image,kind:"material",group:"season2Material"}});
  }catch{}

  async function mutateSave(mutator){
    if(!cloudReady||!currentMemberKey)throw new Error("Firebase ยังไม่พร้อม");
    await settlePendingCloudSave();const {db,fs}=await getFirebaseContext(),ref=fs.doc(db,"saves",currentMemberKey);let next;
    await fs.runTransaction(db,async tx=>{const snap=await tx.get(ref);if(!snap.exists())throw new Error("ไม่พบเซฟสมาชิก");const s=normalizeState(snap.data(),currentMember);assertCurrentCloudSession(snap.data(),currentMember);mutator(s);next=s;tx.set(ref,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false})});
    applyState(next);return next;
  }

  function ensureRepairOverlay(){
    const stage=$("alpacaPenStage");if(!stage)return null;let box=$("s2BrokenPenOverlay");
    if(!box){stage.insertAdjacentHTML("beforeend",'<div id="s2BrokenPenOverlay" class="s2-broken-pen-overlay hidden"><img src="decor-broken-pen.png" alt="คอกพัง"><b>คอกพัง</b><button id="s2RepairPenBtn" type="button">ซ่อมคอก</button></div>');box=$("s2BrokenPenOverlay");$("s2RepairPenBtn").onclick=showRepair}
    return box;
  }
  function paintBroken(){
    const n=currentPenNo(),p=activeState()?.alpaca?.pens?.[n-1],stage=$("alpacaPenStage"),box=ensureRepairOverlay();if(!stage||!p)return;
    stage.classList.toggle("s2-pen-broken",Boolean(p.broken));box?.classList.toggle("hidden",!p.broken);
    const rank=$("alpacaRankBtn");if(rank)rank.classList.toggle("hidden",!isS2Admin());
  }
  async function touchPen(n=currentPenNo()){
    try{const base=activeState();if(!base?.alpaca?.pens?.[n-1])return;const next=normalizeState(cloneData(base),currentMember),p=next.alpaca.pens[n-1],now=gameNow(),last=Number(p.lastVisitedAt)||now;if(!p.broken&&now-last>=BREAK_MS)p.broken=true;if(!p.broken)p.lastVisitedAt=now;applyState(next);try{queueCloudSave()}catch{}paintBroken()}catch(e){console.warn("S2 touch pen",e)}
  }

  function repairRows(){
    const s=activeState();return Object.entries(MATERIALS).map(([k,m])=>{const have=int(s?.specials?.[k]),ok=have>=m.need;return `<article class="s2-repair-item ${ok?"ready":"missing"}"><img src="${m.image}" alt="${safeHtml(m.name)}"><div><b>${safeHtml(m.name)}</b><small>มี ${have.toLocaleString("th-TH")}</small></div><strong>${m.need}</strong></article>`}).join("")
  }
  function showRepair(){
    const n=currentPenNo(),p=activeState()?.alpaca?.pens?.[n-1];if(!p?.broken)return;const enough=Object.entries(MATERIALS).every(([k,m])=>int(activeState()?.specials?.[k])>=m.need);
    $("modalContent").innerHTML=`<section class="feature-panel alpaca-panel s2-repair-panel"><div class="alpaca-panel-hero"><img class="alpaca-hero-icon" src="decor-broken-pen.png" alt=""><div><h2>ซ่อมคอก ${n}</h2><p>ต้องซ่อมก่อนจึงจะใช้งานคอกได้</p></div></div><div class="s2-repair-grid">${repairRows()}</div><button id="s2RepairConfirm" class="primary-spooky-action" type="button" ${enough?"":"disabled"}>ซ่อมคอก</button><button id="s2RepairClose" class="secondary-action" type="button">ปิด</button></section>`;openModal();$("s2RepairConfirm").onclick=repairPen;$("s2RepairClose").onclick=closeModal;
  }
  async function repairPen(){
    const n=currentPenNo(),b=$("s2RepairConfirm");if(b){b.disabled=true;b.textContent="กำลังซ่อม..."}
    try{await mutateSave(s=>{const p=s.alpaca?.pens?.[n-1];if(!p?.broken)throw new Error("คอกนี้ซ่อมแล้ว");for(const [k,m] of Object.entries(MATERIALS))if(int(s.specials?.[k])<m.need)throw new Error(`${m.name}ไม่พอ`);for(const [k,m] of Object.entries(MATERIALS))s.specials[k]=int(s.specials[k])-m.need;p.broken=false;p.lastVisitedAt=gameNow()});closeModal();paintBroken();showWeatherToast?.(`🔨 ซ่อมคอก ${n} สำเร็จแล้ว`)}catch(e){message("ซ่อมคอกไม่ได้",e.message||"วัตถุดิบไม่ครบ")}
  }

  /* Broken pens block every pen action except leaving/switching pens and repairing. */
  document.addEventListener("click",ev=>{
    const stage=$("alpacaPenStage");if(!stage||!stage.classList.contains("s2-pen-broken"))return;
    if(ev.target?.closest?.("#alpacaPenBackBtn,#alpacaPenSwitchBtn,#s2RepairPenBtn,#s2BrokenPenOverlay"))return;
    if(ev.target?.closest?.("#alpacaPenStage")){ev.preventDefault();ev.stopImmediatePropagation();showRepair()}
  },true);

  /* Detect entry and pen changes after the existing Season 1 handlers have rendered. */
  document.addEventListener("click",ev=>{
    if(ev.target?.closest?.("#shortcutAlpacaPenBtn"))setTimeout(()=>touchPen(1),80);
    const pick=ev.target?.closest?.("[data-alpaca-pen]");if(pick)setTimeout(()=>touchPen(Math.max(1,Math.min(5,Number(pick.dataset.alpacaPen)||1))),80);
  },false);

  /* Left building = processing factory. Right building = one combined food/medicine craft hub. */
  let oldFoodHandler=null,oldMedicineHandler=null,oldTroughHandler=null;
  function showCraftHub(){
    if($("alpacaPenStage")?.classList.contains("s2-pen-broken"))return showRepair();
    $("modalContent").innerHTML='<section class="feature-panel alpaca-panel s2-craft-hub"><h2>🦙 โรงเรือนคราฟอัลปาก้า</h2><p>เลือกสิ่งที่ต้องการคราฟ</p><div class="s2-craft-hub-grid"><button id="s2CraftFood"><img src="alpaca-hay-pack.png" alt=""><b>คราฟอาหาร</b></button><button id="s2CraftMedicine"><img src="alpaca-happiness-potion.png" alt=""><b>คราฟยา</b></button></div><button id="s2CraftHubClose" class="secondary-action">ปิด</button></section>';openModal();$("s2CraftFood").onclick=()=>globalThis.YN_ALPACA_CORE?.showCraft?.("food");$("s2CraftMedicine").onclick=()=>globalThis.YN_ALPACA_CORE?.showCraft?.("medicine");$("s2CraftHubClose").onclick=closeModal;
  }
  function bindSceneHotspots(){
    const left=$("alpacaMedicineHotspot"),right=$("alpacaFoodHotspot"),old=$("alpacaTroughHotspot");if(!left||!right||!old)return;
    if(!oldMedicineHandler&&typeof left.onclick==="function")oldMedicineHandler=left.onclick;if(!oldFoodHandler&&typeof right.onclick==="function")oldFoodHandler=right.onclick;if(!oldTroughHandler&&typeof old.onclick==="function")oldTroughHandler=old.onclick;
    left.setAttribute("aria-label","โรงงานแปรรูปอัลปาก้า");left.onclick=()=>{$("alpacaPenStage")?.classList.contains("s2-pen-broken")?showRepair():globalThis.YN_V240?.showFactory?.()};
    right.setAttribute("aria-label","อาคารคราฟอาหารและยาอัลปาก้า");right.onclick=showCraftHub;
    old.classList.add("hidden");
    const nameBtn=$("alpacaPenNameBtn");if(nameBtn){nameBtn.onclick=null;nameBtn.classList.add("hidden")}
    const rank=$("alpacaRankBtn");if(rank&&isS2Admin())rank.onclick=()=>globalThis.YN_ALPACA_CORE?.showRank?.();
    const stage=$("alpacaPenStage");if(stage&&!$("s2TroughLeft")){stage.insertAdjacentHTML("beforeend",'<button id="s2TroughLeft" class="s2-trough-hotspot left" type="button" aria-label="รางอาหารซ้าย"></button><button id="s2TroughRight" class="s2-trough-hotspot right" type="button" aria-label="รางอาหารขวา"></button>');$("s2TroughLeft").onclick=()=>globalThis.YN_ALPACA_CORE?.showTrough?.();$("s2TroughRight").onclick=()=>globalThis.YN_ALPACA_CORE?.showTrough?.()}
  }

  /* Factory interior is handled by CSS. Avoid MutationObserver/style polling: it caused input lag on phones. */
  function periodic(){bindSceneHotspots();paintBroken();const r=$("alpacaRankBtn");if(r)r.classList.toggle("hidden",!isS2Admin())}
  setTimeout(()=>{bindSceneHotspots();periodic()},250);
  setInterval(periodic,10000);

  window.YAINOO_BUILD="S2V003-ALPACA-FIX3-FAST";
  console.info("S2V003 alpaca fix3 fast loaded");
})();


