      Object.assign(cat,{placedFarm:-1,placedHotel:true,hotelPen:pen,placedAt:now,expiresAt:now+CAT_LIFETIME_MS,nextFeedAt:now,nextDropAt:now+CAT_DROP_INTERVAL_MS,drops:[]});
