  function scheduleCatSlow(c){if(currentScene!=="dogHotel"||!c.el?.isConnected)return;setCatPose(c,Math.floor(Math.random()*12));c.timer=setTimeout(()=>moveCatSlow(c),320+Math.random()*580)}
