    truffle:{name:"เห็ดทรัฟเฟิลหลอน",icon:"🍄",image:"pig_truffle_transparent.png?v=S2R9"},
    shadowPork:{name:"เนื้อหมูเงามรณะ",icon:"🥩",image:"pig_meat_transparent.png?v=S2R9"},
